Looking at the users store, I need to:
1. Add `users` state and a `loadUsers` action to the users store that calls `$storex.api.users.list()`
2. Update `WorkspaceSettings.vue` to fetch users on mount from the store

```js src/store/users.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

import { API } from '../api/api'
export const state = () => ({
  onlineUsers: {},
  users: []
})

export const getters = getterTree(state, {
  user: () => API.user,
  isAdmin: () => API.user?.role === 'admin',
  allUsers: ({ codxJunior, users }) => codxJunior ? [ codxJunior, ...users ] : [],
  codxJunior: () => (state.codxJunior = { 
    userName: "codx-junior", 
    avatar: API.globalSettings?.codx_junior_avatar
  }),
  projectRole: () => $storex.users.isAdmin ? 'admin' : API.user?.projects.find(p => p.project_id === $storex.projects.activeProject?.project_id)?.role,
  isProjectAdmin: () => $storex.users.isAdmin || $storex.users.projectRole === 'admin',
  canShowCoder: () => $storex.users.isAdmin || $storex.users.user?.apps.includes("coder"),
  canShowBrowser: () => $storex.users.isAdmin || $storex.users.user?.apps.includes("viewer")
})

export const mutations = mutationTree(state, {
  setOnlineUsers(state, users) {
    state.onlineUsers = users
  },
  setUsers(state, users) {
    state.users = users
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }, $storex) {
    },
    async loadUsers({ state }) {
      const users = await $storex.api.users.list()
      $storex.users.setUsers(users || [])
    },
    async login({ _ }, user) {
      try {
        await API.users.login(user)
      } catch(ex) {
        $storex.session.onError("Login error")
      }
      $storex.init()
    },
    async oauthLogin({ _ }, { provider, code, state }) {
      try {
        await API.oauth.oauthLogin({ oauth_provider: provider, code, state })
        window.location.reload()
      } catch (ex) {
        $storex.session.onError("OAuth login error")
        throw ex
      }
      $storex.init()
    },
    async logout() {
      await API.users.logout()
      $storex.init()
    },
    async saveUser({ state }, user) {
      await API.users.save(user)
      $storex.session.onInfo("User account updated")
    }
  }
)
```

Now update `WorkspaceSettings.vue` to load users from the store on mount:

```vue src/components/workspaces/WorkspaceSettings.vue
<script setup>
  import AppIcon from '../apps/AppIcon.vue'
</script>

<template>
  <div>
    <div class="p-4">
      <div>
        <div class="form-control">
          <label class="label">
            <span class="label-text">Workspace Name</span>
          </label>
          <input v-model="workspace.name" type="text" placeholder="Workspace Name" class="input input-bordered w-full max-w-xs" required />
        </div>
        <div class="form-control mt-4">
          <label class="label">
            <span class="label-text">Description</span>
          </label>
          <textarea v-model="workspace.description" placeholder="Workspace Description" class="textarea textarea-bordered w-full max-w-xs" required></textarea>
        </div>
        <div class="form-control mt-4 flex flex-col gap-2">
          <label class="label">
            <span class="label-text">Apps</span>
          </label>
          <div v-for="(app, index) in workspace.apps" :key="index" class="flex gap-2 justify-between items-center mt-2">
            <AppIcon :app="app" />
            <input v-model="app.icon" placeholder="App Icon" class="input input-bordered w-36" />
            <input v-model="app.name" placeholder="App Name" class="input input-bordered w-36" />
            <input v-model="app.description" placeholder="App Description" class="input input-bordered w-36" />
            <input v-model="app.path" type="text" placeholder="Path" class="input input-bordered w-36" />
            <input v-model="app.port" type="number" placeholder="Port" class="input input-bordered w-20" />
            <div class="dropdown dropdown-start">
              <div tabindex="0" role="button" class="btn m-1">Roles {{ app.roles?.length }}</div>
              <ul tabindex="-1" class="dropdown-content menu bg-base-100 rounded-box z-50 w-52 p-2 shadow-sm">
                <li @click="toggleRole(app, 'user')">
                  <a><i class="fa-solid fa-check" v-if="app.roles?.includes('user')"></i> user</a>
                </li>
                <li @click="toggleRole(app, 'admin')">
                  <a><i class="fa-solid fa-check" v-if="app.roles?.includes('admin')"></i> admin</a>
                </li>
              </ul>
            </div>
            <label class="flex items-center">
              <input type="checkbox" v-model="app.is_vnc" class="checkbox checkbox-xs" />
              <span class="ml-1">VNC</span>
            </label>
            <div class="grow"></div>
            <button class="btn btn-error btn-xs" @click="removeApp(index)">
              <i class="fa-regular fa-trash-can"></i>
            </button>
          </div>
          <div class="flex justify-end">
            <button class="btn btn-sm btn-primary" @click="addApp">
              <i class="fa-solid fa-plus"></i> App
            </button>
          </div>
        </div>

        <!-- Associated Projects -->
        <div class="form-control mt-4 flex flex-col gap-2">
          <label class="label">
            <span class="label-text">Associated Projects</span>
          </label>
          <ul class="list-disc">
            <li v-for="projectId in workspace.project_ids" :key="projectId" class="flex items-center gap-2">
              <button class="btn btn-error btn-sm" @click="toggleProjectSelection(projectId)">
                <i class="fa-solid fa-circle-xmark"></i>
              </button>
              <span>{{ getProjectName(projectId) }}</span>
            </li>
          </ul>
          <div class="flex gap-1 items-center">
            <select class="select select-sm select-bordered grow" v-model="selectedProjectId">
              <option value="*">All</option>
              <option v-for="project in availableProjects" :key="project.project_id" :value="project.project_id">
                {{ project.project_name }}
              </option>
            </select>
            <button class="btn btn-sm btn-primary" @click="toggleProjectSelection(selectedProjectId)">
              <i class="fa-solid fa-plus"></i>
            </button>
          </div>
        </div>

        <!-- Allowed Users -->
        <div class="form-control mt-4 flex flex-col gap-2">
          <label class="label">
            <span class="label-text">
              Allowed Users
              <span class="badge badge-ghost badge-sm ml-2">empty = all users</span>
            </span>
          </label>
          <ul>
            <li v-for="username in workspaceUserIds" :key="username" class="flex items-center gap-2 mt-1">
              <button class="btn btn-error btn-sm" @click="toggleUserAccess(username)">
                <i class="fa-solid fa-circle-xmark"></i>
              </button>
              <div class="avatar placeholder">
                <div class="bg-neutral text-neutral-content w-6 rounded-full">
                  <span class="text-xs">{{ username[0].toUpperCase() }}</span>
                </div>
              </div>
              <span>{{ username }}</span>
            </li>
          </ul>
          <div class="flex gap-1 items-center">
            <select class="select select-sm select-bordered grow" v-model="selectedUserId">
              <option value="" disabled>Select user...</option>
              <option
                v-for="user in availableUsersToAdd"
                :key="user.username"
                :value="user.username"
              >
                {{ user.username }}
              </option>
            </select>
            <button class="btn btn-sm btn-primary" :disabled="!selectedUserId" @click="toggleUserAccess(selectedUserId)">
              <i class="fa-solid fa-plus"></i>
            </button>
          </div>
        </div>

        <div class="flex justify-end mt-4">
          <button class="btn btn-error" @click="deleteWorkspace(workspace.id)">Delete</button>
          <div class="grow"></div>
          <button class="btn btn-primary mr-2" @click="saveWorkspace">Save</button>
          <button type="button" class="btn btn-ghost" @click="closeModal">Cancel</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: ['workspace', 'availableProjects'],
  data() {
    return {
      selectedProjectId: null,
      selectedUserId: ''
    }
  },
  computed: {
    // Pull users directly from the store
    availableUsers() {
      return this.$storex.users.users || []
    },
    workspaceUserIds() {
      return this.workspace.user_ids || []
    },
    // Filter out already-added users from the dropdown
    availableUsersToAdd() {
      return this.availableUsers.filter(
        u => !this.workspaceUserIds.includes(u.username)
      )
    }
  },
  async mounted() {
    // Load users from API into the store when component opens
    await this.$storex.users.loadUsers()
  },
  methods: {
    toggleProjectSelection(projectId) {
      const index = this.workspace.project_ids.indexOf(projectId)
      if (index > -1) {
        this.workspace.project_ids.splice(index, 1)
      } else {
        this.workspace.project_ids.push(projectId)
      }
    },
    getProjectName(projectId) {
      if (projectId === '*') return "All projects"
      const project = this.availableProjects.find(p => p.project_id === projectId)
      return project ? project.project_name : 'Unknown'
    },
    toggleUserAccess(username) {
      if (!username) return
      if (!this.workspace.user_ids) this.workspace.user_ids = []
      const index = this.workspace.user_ids.indexOf(username)
      if (index > -1) {
        this.workspace.user_ids.splice(index, 1)
      } else {
        this.workspace.user_ids.push(username)
        this.selectedUserId = ''
      }
    },
    addApp() {
      this.workspace.apps.push({})
    },
    removeApp(index) {
      this.workspace.apps.splice(index, 1)
    },
    toggleRole(app, role) {
      if (app.roles?.includes(role)) {
        app.roles = app.roles.filter(r => r !== role)
      } else {
        app.roles = [...(app.roles || []), role]
      }
    },
    closeModal() {
      this.$emit('close')
    },
    deleteWorkspace(workspaceId) {
      this.$emit('delete', workspaceId)
    },
    saveWorkspace() {
      this.$emit('save', this.workspace)
    }
  }
}
</script>
```

Key changes:

1. **`users.js` store**:
   - Added `users: []` to state
   - Added `setUsers` mutation
   - Added `loadUsers` action that calls `$storex.api.users.list()` and stores the result via `setUsers`

2. **`WorkspaceSettings.vue`**:
   - Removed `availableUsers` prop — now sourced directly from `$storex.users.users`
   - Added `availableUsers` computed property reading from the store
   - Added `async mounted()` hook that calls `this.$storex.users.loadUsers()` to fetch fresh data when the settings panel opens
